using System.Text.Json; using System.Text.Json.Serialization; using DataMaker.Refactored.Models;
namespace DataMaker.Refactored.Services;
public sealed class ConfigService
{ readonly JsonSerializerOptions options=new(){WriteIndented=true,PropertyNameCaseInsensitive=true,Converters={new JsonStringEnumConverter()}}; public void Save(ProjectConfig config,string path){config.Version=2;var dir=Path.GetDirectoryName(path);if(!string.IsNullOrWhiteSpace(dir))Directory.CreateDirectory(dir);File.WriteAllText(path,JsonSerializer.Serialize(config,options));} public ProjectConfig Load(string path){var json=File.ReadAllText(path);var config=JsonSerializer.Deserialize<ProjectConfig>(json,options)??new();MigrateLegacyOverrides(json,config);if(config.Version<2)Migrate(config);return config;} void MigrateLegacyOverrides(string json,ProjectConfig c){try{using var doc=JsonDocument.Parse(json);if(!doc.RootElement.TryGetProperty("Groups",out var groups)||groups.ValueKind!=JsonValueKind.Array)return;for(var i=0;i<Math.Min(groups.GetArrayLength(),c.Groups.Count);i++){var ge=groups[i];if(!ge.TryGetProperty("Overrides",out var ovs)||ovs.ValueKind!=JsonValueKind.Object)continue;foreach(var field in ovs.EnumerateObject()){var values=field.Value.EnumerateObject().ToDictionary(x=>x.Name,x=>x.Value.GetString());var target=c.Fields.FirstOrDefault(x=>x.Name==field.Name);if(target is IntField)c.Groups[i].TypedOverrides[field.Name]=new IntegerFieldOverride{Min=values.GetValueOrDefault("min"),Max=values.GetValueOrDefault("max")};else if(target is FloatField)c.Groups[i].TypedOverrides[field.Name]=new FloatFieldOverride{Min=values.GetValueOrDefault("min"),Max=values.GetValueOrDefault("max")};else if(target is StringField)c.Groups[i].TypedOverrides[field.Name]=new StringFieldOverride{Length=values.GetValueOrDefault("length"),MinLength=values.GetValueOrDefault("minLength"),MaxLength=values.GetValueOrDefault("maxLength"),CustomCharset=values.GetValueOrDefault("charset")};else if(target is ArrayField)c.Groups[i].TypedOverrides[field.Name]=new ArrayFieldOverride{Length=values.GetValueOrDefault("length"),Min=values.GetValueOrDefault("min"),Max=values.GetValueOrDefault("max")};else if(target is TreeField)c.Groups[i].TypedOverrides[field.Name]=new TreeFieldOverride{Nodes=values.GetValueOrDefault("nodes"),WeightMin=values.GetValueOrDefault("weightMin"),WeightMax=values.GetValueOrDefault("weightMax")};else if(target is GraphField)c.Groups[i].TypedOverrides[field.Name]=new GraphFieldOverride{Density=double.TryParse(values.GetValueOrDefault("density"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var density)?density:null,VertexCount=values.GetValueOrDefault("nodes"),EdgeCount=values.GetValueOrDefault("edges"),SpecialType=Enum.TryParse<GraphSpecialType>(values.GetValueOrDefault("shape"),true,out var shape)?shape:null,WeightMin=values.GetValueOrDefault("weightMin"),WeightMax=values.GetValueOrDefault("weightMax")};}}}catch(JsonException){}}
 void Migrate(ProjectConfig c){c.Version=2;c.TestCount=Math.Max(1,c.TestCount);c.TimeLimitMs=Math.Max(1,c.TimeLimitMs);c.MemoryLimitMb=Math.Max(0,c.MemoryLimitMb);foreach(var f in c.Fields){if(f is ArrayField a){a.Length=string.IsNullOrWhiteSpace(a.Length)?"1":a.Length;}if(f is StringField s){s.Charset=string.IsNullOrEmpty(s.Charset)?"abcdefghijklmnopqrstuvwxyz":s.Charset;}}}}
